entries[242555] = { ["name"] = "Ashbringer", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Sword\n5 - 9 Damage Speed 3.60\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Retribution Paladin\n\"So it was that over the course of time, the man and the weapon seemed as one. Ashbringer became a name of legend, attributed not just to the fearsome blade but also to the relentless knight who wielded it.\"\nSell Price:" }
entries[242556] = { ["name"] = "Twinblades of the Deceiver", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Warglaive\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequires Havoc Demon Hunter\n\"Make examples of those foolish enough to oppose you, and the rest of their kind will grovel at your feet.\"\nSell Price:" }
entries[242557] = { ["name"] = "Twinblades of the Deceiver", ["text"] = "Binds when picked up\nUnique\nOff Hand Warglaive\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequires Havoc Demon Hunter\n\"The end has come! Let the unravelling of this world commence!\"\nSell Price:" }
entries[242558] = { ["name"] = "Aluneth", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Mage\nEquip: Grants the Mark of Aluneth ability, which places a rune on the ground that explodes for massive damage after a short delay.\nRequires level 10 to 90 ( 90)\nRequires Arcane Mage\n\"After many setbacks, Aegwynn finally bound the entity to an enchanted greatstaff. The task of containing Aluneth was done, but it would take the Guardian years to truly harness its power.\"\nSell Price:" }
entries[242559] = { ["name"] = "Blades of the Fallen Prince", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Sword\n2 - 5 Damage Speed 2.60\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Frost Death Knight\n\"When my days have come to an end, you shall be king.\"\nSell Price:" }
entries[242560] = { ["name"] = "Blades of the Fallen Prince", ["text"] = "Binds when picked up\nUnique\nOff Hand Sword\n2 - 5 Damage Speed 2.60\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Frost Death Knight\n\"I will show you the justice of the grave... and the true meaning of fear.\"" }
entries[242561] = { ["name"] = "G'Hanir, the Mother Tree", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Restoration Druid\n\"At the beginning, there was a source of healing and balance, a place where all life could rest and revive.\"\nSell Price:" }
