entries[242563] = { ["name"] = "Apocalypse", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Sword\n5 - 9 Damage Speed 3.60\n(1.9 damage per second)\n+3 Strength\n+4 Stamina\nClasses: Death Knight\nRequires level 10 to 90 ( 90)\nRequires Unholy Death Knight\n\"It shall sow destruction and war. Famine and death. It shall tempt with power, and then bring an end to all life.\"\nSell Price:" }
