entries[242568] = { ["name"] = "Felo'melorn", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequires Fire Mage\n\"...not elven weapons. Not when they are reforged with magic, and hatred, and a burning need for revenge. No, Arthas. Felo'melorn is stronger than ever-as am I. - Kael'thas Sunstrider\"\nSell Price:" }
entries[242569] = { ["name"] = "Claws of Ursoc", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Fist Weapon\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Guardian Druid\n\"Ursoc, brother of Ursol and guardian of the furbolg tribes... bearer of the strength of the forest itself.\"\nSell Price:" }
entries[242570] = { ["name"] = "Claws of Ursoc", ["text"] = "Binds when picked up\nUnique\nOff Hand Fist Weapon\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Guardian Druid\n\"Azeroth will need you. If you do not stand ready, the world may fall.\"\nSell Price:" }
entries[242571] = { ["name"] = "The Silver Hand", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Mace\n2 - 4 Damage Speed 3.60\n(0.8 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Holy Paladin\n\"Tyr replied that he did not consider his argent hand a reminder of defeat. For him it was a symbol of the sacrifice he had made to defend Azeroth, and he wanted the world to see it that way as well.\"\nSell Price:" }
entries[242573] = { ["name"] = "T'uure, Beacon of the Naaru", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Holy Priest\n\"Blessed are the torchbearers, who bring light to the darkness.\"\nSell Price:" }
entries[242574] = { ["name"] = "Thas'dorah, Legacy of the Windrunners", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nRanged Bow\n5 - 7 Damage Speed 3.00\n(2.0 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Hunter\nRequires level 10 to 90 ( 90)\nRequires Marksmanship Hunter\n\"When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"\"\nSell Price:" }
entries[242575] = { ["name"] = "Xal'atath, Blade of the Black Empire", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Dagger\n1 - 2 Damage Speed 1.80\n(0.8 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Shadow Priest\n\"Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.\"\nSell Price:" }
entries[242576] = { ["name"] = "Aldrachi Warblades", ["text"] = "Binds when picked up\nUnique\nOff Hand Warglaive\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequires Vengeance Demon Hunter\n\"His warblades howled over the clamor of battle, rending anything that came near. Each demon Toranaar vanquished seemed to fill him with renewed vigor and strength. He was an army unto himself.\"" }
entries[242577] = { ["name"] = "Aldrachi Warblades", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Warglaive\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+7 Intellect\n+1 [Agility or Intellect]\n+2 Stamina\nClasses: Demon Hunter\nRequires level 10 to 90 ( 90)\nRequires Vengeance Demon Hunter\n\"The Aldrachi were a proud race. Too proud to serve. Millions of demons died before the Aldrachi were wiped out, and it took Sargeras himself to kill their king.\"" }
entries[242578] = { ["name"] = "Scythe of Elune", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Balance Druid\n\"There is power within that would be freed. With balance and control, the wolf may be tamed, but only for a time.\"\nSell Price:" }
entries[242579] = { ["name"] = "Fangs of Ashamane", ["text"] = "Binds when picked up\nUnique\nOff Hand Dagger\n2 - 3 Damage Speed 1.80\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Feral Druid\n\"She ripped through the demons' ranks and then disappeared into the trees. She crept along the high branches and dove down upon the Legion commanders. She was a terror, a fearsome beast, and she held nothing back, offering no mercy.\"\nSell Price:" }
entries[242580] = { ["name"] = "Fangs of Ashamane", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Dagger\n2 - 3 Damage Speed 1.80\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Druid\nRequires level 10 to 90 ( 90)\nRequires Feral Druid\n\"The sacrifice of Ashamane is remembered to this day. We live by her grace, and her children still tread the forests with us as our closest companions.\"\nSell Price:" }
entries[242581] = { ["name"] = "Titanstrike", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nRanged Gun\n4 - 8 Damage Speed 3.00\n(2.0 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Hunter\nRequires level 10 to 90 ( 90)\nRequires Beast Mastery Hunter\n\"A peerless example of techno-magical engineering, infused with the power of storms.\"\nSell Price:" }
entries[242582] = { ["name"] = "Ebonchill", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequires Frost Mage\n\"Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.\"\nSell Price:" }
entries[242583] = { ["name"] = "Truthguard", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nOff Hand Shield\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Protection Paladin\n\"With the first hammer fall, rivers of magma spilled from the icy mountains. With the second, the sky howled and lightning set the heavens aflame. With the third, a single ray of sunlight pierced the storm clouds and whispered over Truthguard's surface.\"\nSell Price:" }
entries[242584] = { ["name"] = "Oathseeker", ["text"] = "Binds when picked up\nUnique\nMain Hand Sword\n2 - 5 Damage Speed 2.60\n(1.3 damage per second)\n+1 Strength\n+2 Stamina\nClasses: Paladin\nRequires level 10 to 90 ( 90)\nRequires Protection Paladin\n\"Killing for the sake of killing... conquering for the sake of conquest... there is no honor in such things. There is only shame and regret.\"\nSell Price:" }
entries[242585] = { ["name"] = "Light's Wrath", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Discipline Priest\n\"It was with our greatest hopes and prayers that we attended the ceremony that day... and it is with our greatest sorrows that we departed it.\"\nSell Price:" }
entries[242586] = { ["name"] = "The Kingslayers", ["text"] = "Binds when picked up\nUnique\nOff Hand Dagger\n2 - 3 Damage Speed 1.80\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequires Assassination Rogue\n\"It was not a pleasant death. But it was fast, quiet, and efficient. When the orc took his last breath, the wound that killed him became irregular. Nobody would be able to tell whether he had died to a knife, an axe, or a spear.\"\nSell Price:" }
entries[242587] = { ["name"] = "The Kingslayers", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Dagger\n2 - 3 Damage Speed 1.80\n(1.4 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequires Assassination Rogue\n\"Countless voices hushed, and countless leaders toppled... all at the whim of his foul command. There would be no redemption for these acts, only solitude and sorrow.\"\nSell Price:" }
entries[242588] = { ["name"] = "The Dreadblades", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Sword\n2 - 5 Damage Speed 2.60\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequires Outlaw Rogue\n\"She saw herself commanding an impossibly large pirate fleet, one that could conquer the high seas and all the nations of Azeroth. Every ship that dared to challenge her burned, and every city gave up its treasures or was destroyed.\"\nSell Price:" }
entries[242589] = { ["name"] = "Fury of the Stonemother", ["text"] = "Binds when picked up\nUnique\nOff Hand Mace\n3 - 4 Damage Speed 2.60\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequires Enhancement Shaman\n\"Created through the power of Doomhammer and the powerful shaman who wields it.\"\nSell Price:" }
entries[242591] = { ["name"] = "Sharas'dal, Scepter of Tides", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Mace\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequires Restoration Shaman\n\"They drifted into the abyss, but Azshara and her Highborne remained unbroken. The darkness around them was absolute, and so the queen willed Sharas'dal to bring them light...\"\nSell Price:" }
entries[242592] = { ["name"] = "Shield of the Sea Queen", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequires Restoration Shaman\n\"As the ocean crushed the life from their bodies, ancient creatures stirred in the darkness. Their whispers flowed through the currents. Their powers wrapped tight around the queen and her servants.\"\nSell Price:" }
entries[242593] = { ["name"] = "The Fist of Ra-den", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Fist Weapon\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequires Elemental Shaman\n\"To seal Al'Akir's demise, Master Ra slammed his fist into the mountaintop. The heavens split wide, and all the fire and fury they contained crashed down atop the Windlord's head.\"\nSell Price:" }
entries[242594] = { ["name"] = "The Highkeeper's Ward", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n44 Armor\n+1 Strength\n+4 Intellect\n+2 Stamina\nClasses: Shaman\nRequires level 10 to 90 ( 90)\nRequires Elemental Shaman\n\"Ra and Helya crafted a shield, the Highkeeper's Ward, to act as a key to the Elemental Plane. It thrummed with the energies of the four elements, which Ra could call upon whenever he desired.\"\nSell Price:" }
entries[242595] = { ["name"] = "Sheilun, Staff of the Mists", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequires Mistweaver Monk\n\"You seek the calm, inevitable force of a deep river, the kind that carves canyons into the toughest stone and carries away warriors on its currents without so much as a ripple. Sheilun is the embodiment of that idea.\"\nSell Price:" }
entries[242596] = { ["name"] = "Fu Zan, the Wanderer's Companion", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n6 - 8 Damage Speed 3.60\n(1.9 damage per second)\n+3 Agility\n+4 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequires Brewmaster Monk\n\"From the beginning, this staff has accompanied legendary creatures and immortal spirits as they carried out important, lasting work all across Azeroth.\"\nSell Price:" }
entries[242597] = { ["name"] = "Fists of the Heavens", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMain Hand Fist Weapon\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequires Windwalker Monk\n\"When Irmaat hefted his two weapons and tested the power within them, uncontrollable fury spilled forth.\"\nSell Price:" }
entries[242598] = { ["name"] = "Scepter of Sargeras", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequires Destruction Warlock\n\"When at last the moment arrived for Ner'zhul to act, he did so with wild abandon, heedless of the consequences. It mattered not to him if Draenor was destroyed; in fact, he welcomed it as part of his legacy.\"\nSell Price:" }
entries[242599] = { ["name"] = "Ulthalesh, the Deadwind Harvester", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nTwo-Hand Staff\n3 - 4 Damage Speed 3.60\n(1.0 damage per second)\n+12 Intellect\n+4 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequires Affliction Warlock\n\"The scythe's master will either overcome Sataiel or be consumed, which will only make the blade more powerful. And then another bearer will take their place. And another.\"\nSell Price:" }
entries[242600] = { ["name"] = "Skull of the Man'ari", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequires Demonology Warlock\n\"When finally Thal'kiel emerged, he was changed. He had aged by centuries, alone in the dark with his thoughts and his thralls. His back was twisted and stooped, and there was an odd glimmer in his eye. He summoned his Wakeners, and we answered the call...\"\nSell Price:" }
entries[242601] = { ["name"] = "Fists of the Heavens", ["text"] = "Binds when picked up\nUnique\nOff Hand Fist Weapon\n3 - 5 Damage Speed 2.60\n(1.5 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Monk\nRequires level 10 to 90 ( 90)\nRequires Windwalker Monk\n\"There was a great flash of light and a great rush of air, and when it was done, Irmaat could feel his weapons, Al'burq and Alra'ed trembling with elemental power.\"\nSell Price:" }
entries[242602] = { ["name"] = "Secrets of the Void", ["text"] = "Binds when picked up\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Priest\nRequires level 10 to 90 ( 90)\nRequires Shadow Priest\n\"The moment I touched the blade, a name was spoken in my mind: Xal'atath. I knew then that I could not destroy the dagger. Not yet. How can one defeat a power she does not understand?\"\nSell Price:" }
entries[242603] = { ["name"] = "Heart of the Phoenix", ["text"] = "Binds when picked up\nHeld In Off-hand\n+4 Intellect\n+2 Stamina\nClasses: Mage\nRequires level 10 to 90 ( 90)\nRequires Fire Mage\n\"When the fighting was done, Dath'Remar stood painted in demon blood. As night fell, we knew that more battles remained, and yet, with this elf and this blade among us, we held out hope that victory did not lie beyond our grasp.\"\nSell Price:" }
entries[242604] = { ["name"] = "The Dreadblades", ["text"] = "Binds when picked up\nUnique\nOff Hand Sword\n2 - 5 Damage Speed 2.60\n(1.3 damage per second)\n+1 Agility\n+2 Stamina\nClasses: Rogue\nRequires level 10 to 90 ( 90)\nRequires Outlaw Rogue\n\"No blade can shed the blood of so many innocents and not demand a toll on its wielder as well. They are no treasure.\"\nSell Price:" }
entries[242605] = { ["name"] = "Spine of Thal'kiel", ["text"] = "Binds when picked up\nUnique\nMain Hand Dagger\n1 - 2 Damage Speed 1.80\n(0.8 damage per second)\n+8 Intellect\n+2 Stamina\nClasses: Warlock\nRequires level 10 to 90 ( 90)\nRequires Demonology Warlock\n\"The Wakeners' screams echoed across Argus, as a grim reminder of the price paid for dealing with demons.\"\nSell Price:" }
entries[242606] = { ["name"] = "Tenebrous Amethyst", ["text"] = "Amethyst\nCrafting Reagent\n\"Acquired by Jewelcrafters when prospecting Midnight ore. Can be bought and sold on the Auction House.\"\nSell Price:" }
