entries[242617] = { ["name"] = "Curious Simulacrum", ["text"] = "Binds when picked up\nUse: Inspect the simulacrum, revealing its true nature.\nRequires level 10 to 90 ( 90)\n\"This appears to be the artifact weapon you're already holding. What is this sorcery?\"" }
entries[242620] = { ["name"] = "Glimmering Gemdust", ["text"] = "Crafting Reagent\n\"Acquired by Jewelcrafters by crushing Midnight gems. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[242621] = { ["name"] = "Glimmering Gemdust", ["text"] = "Crafting Reagent\n\"Acquired by Jewelcrafters by crushing Midnight gems. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[242622] = { ["name"] = "Warbound Purifying Kit", ["text"] = "Veteran\nBinds when picked up\nUse: Unlock future Veteran items in Horrific Visions Revisited to be Warbound until equipped.\nComplete the Revisited Masked Soliloquy achievement, finishing a complete Horrific Vision with any Faceless Masks active." }
entries[242623] = { ["name"] = "Enchanted Warbound Purifying Kit", ["text"] = "Champion\nBinds when picked up\nUse: Unlock future Champion items in Horrific Visions Revisited to be Warbound until equipped.\nComplete the Revisited Symphony of Masks achievement, finishing a full Horrific Vision with at least 5 Faceless Masks active." }
entries[242627] = { ["name"] = "Chilling Forsaken Blade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242628] = { ["name"] = "Forsaken's Grotesque Blade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"It squeals in delight as it carves through flesh and bone.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242629] = { ["name"] = "Wailing Banshee's Blade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"No wound from this blade ever truly heals.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242630] = { ["name"] = "Sickly Forsaken Blade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242631] = { ["name"] = "Chilling Forsaken Great Blade", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242632] = { ["name"] = "Forsaken's Grotesque Great Blade", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n\"Every body it puts into the ground becomes a nursery for contagion.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242633] = { ["name"] = "Wailing Banshee's Great Blade", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n\"The undead don't have much use for tombstones. Unless... it's a sword.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242634] = { ["name"] = "Sickly Forsaken Great Blade", ["text"] = "Cosmetic\nBinds to Warband\nTwo-Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[242635] = { ["name"] = "Twilight's Blade - Armor - Tabard", ["text"] = "Cosmetic\nBinds to Warband\nTabard\nUse: Add this appearance to your Warband collection." }
entries[242636] = { ["name"] = "Astral Legend's Pennant", ["text"] = "Binds when picked up\nToy\nUse: Represent your seasonal achievement with a pennant. (2 Min Cooldown)" }
entries[242637] = { ["name"] = "Recycle Potions", ["text"] = "\"Break down unwanted potions into Stabilized Derivate.\"" }
entries[242638] = { ["name"] = "Recycle Flasks", ["text"] = "\"Break down unwanted flasks and phials into Stabilized Derivate.\"\nSell Price:" }
entries[242639] = { ["name"] = "Practically Pork", ["text"] = "Crafting Reagent\n\"Meat from various creatures in Midnight zones. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[242640] = { ["name"] = "Plant Protein", ["text"] = "Vegetarian\nCrafting Reagent\n\"A meat substitute from various creatures in Midnight zones. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[242641] = { ["name"] = "Cooking Spirits", ["text"] = "Crafting Reagent\n\"Wine used for cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242642] = { ["name"] = "Thalassian Herbs", ["text"] = "Crafting Reagent\n\"Finely chopped herbs used for cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242643] = { ["name"] = "A Big Ol' Stick of Butter", ["text"] = "Crafting Reagent\n\"Butter used in various Quel'Thalas cooking recipes. Sold by vendors.\"\nSell Price:" }
entries[242644] = { ["name"] = "Mana-Wyrm Essence", ["text"] = "Crafting Reagent\n\"Residue siphoned from Mana-Wyrms to add a little zest in cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242645] = { ["name"] = "Ripened Vegetable Assortment", ["text"] = "Crafting Reagent\n\"Ripe vegetables used for cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242646] = { ["name"] = "Pouch of Spices", ["text"] = "Crafting Reagent\n\"Spices used for cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242647] = { ["name"] = "Tavern Fixings", ["text"] = "Crafting Reagent\n\"A mixture of miscellaneous odds-and-ends used in cooking various Quel'Thalas recipes. Sold by vendors.\"\nSell Price:" }
entries[242648] = { ["name"] = "Black Blood Coagulate", ["text"] = "Binds to Warband\nSell Price:" }
entries[242650] = { ["name"] = "Box of Rocks", ["text"] = "Binds when picked up\n\"Exactly what you expect. Created by experienced alchemists.\"\n<Right Click to Open>\nSell Price:" }
entries[242651] = { ["name"] = "Stabilized Derivate", ["text"] = "Binds when picked up\nCrafting Reagent\n\"A coalesced alchemical essence reclaimed from excess concoctions.\"\nSell Price:" }
entries[242654] = { ["name"] = "Shadowtrade Overstock", ["text"] = "Quest Item\n\"A variety of strange items and creatures from all over.\"\nSell Price:" }
entries[242664] = { ["name"] = "Durable Information Securing Container", ["text"] = "Binds when picked up\nWaist Cloth\n11 Armor\n+20 [Agility or Strength or Intellect]\n+141 Stamina\n\nPrismatic Socket\n\nDurability 55 / 55\nEquip: Your spells and abilities have a chance to turn you into a Lightning Rod striking a random enemy target within 40 yds for ( 1 * 484 ) Nature damage every 3 sec for 15 sec.\nUse: Open the device.\nSell Price:" }
entries[242667] = { ["name"] = "Ba'key's Special Cookie", ["text"] = "Quest Item\nUnique\n\"A sweet honey and spice aroma, reminiscent of dwarven cookies.\"" }
entries[242691] = { ["name"] = "Olemba Lumber", ["text"] = "Binds to Warband\nCrafting Reagent\n\"Lumber harvested on the shattered world of Outland.\"\nSell Price:" }
entries[242693] = { ["name"] = "Kafaccino", ["text"] = "Binds when picked up\nUse: Restores ( 3750 / 5 * 20) mana over 20 sec. Must remain seated while drinking.\n\"Made from the finest beans and steamed yak's milk from Kun-Lai Summit, it'll put pep back in one's step!\"" }
entries[242706] = { ["name"] = "Curious Curio", ["text"] = "Binds when picked up\nUnique\nRequires level 10 to 90 ( 90)\n\"The infinite dragonflight might be interested in this.\"" }
entries[242708] = { ["name"] = "Box of Cookies", ["text"] = "Quest Item\nUnique\n\"A box of Ba'key's special cookies.\"" }
entries[242711] = { ["name"] = "Pungent Truffle", ["text"] = "Binds when picked up\nDuration: 7 days (real time)\nUse: Transform into a sporeling." }
entries[242712] = { ["name"] = "Eversong Diamond", ["text"] = "Diamond\nCrafting Reagent\n\"Acquired by Jewelcrafters when prospecting Midnight ore. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[242713] = { ["name"] = "Resplendent K'arroc", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A technological marvel in the flesh, this K'arroc represents hope for a brighter K'aresh.\"\nWorld Quest:\nThe Hope of K'aresh\nZone:\nK'aresh" }
entries[242714] = { ["name"] = "Umbral K'arroc", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A savage K'arroc particularly well-suited to prowling the perpetual twilight of K'aresh.\"\nAchievement:\nGlory of the Omega Raider\nCategory:\nDungeons & Raids" }
entries[242715] = { ["name"] = "K'arroc Swiftwing", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A gift for services rendered, this K'arroc has seen its share of hazardous flights.\"\nQuest:\nOff to Tazavesh, Again\nZone:\nK'aresh" }
entries[242717] = { ["name"] = "Lavender K'arroc", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This particularly belligerent K'arroc's previous master died while investigating Untethered Space. Perhaps it will accept you instead... or maybe not.\"\nVendor:\nShad'anis\nZone:\nK'aresh\nCost:\n10" }
