entries[242728] = { ["name"] = "The Bone Freezer", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Bitter rival to The Bone Melter, this creeper was ousted from their lair near Manaforge Omega after a crushing defeat. It now seeks to learn from the one that dethroned its greatest foe.\"\nFaction:\nManaforge Vandals\nRenown:\n14\nLocation:\nShadow Point" }
entries[242729] = { ["name"] = "Ruby Void Creeper", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 15 with the K'aresh Trust.\n\n\"Rescued\" by the K'aresh Trust for study, this void creeper has turned out to be an incredibly sturdy mount.\nVendor:\nOm'sirik\nZone:\nK'aresh\nCost:\n8125" }
entries[242730] = { ["name"] = "Acidic Void Creeper", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This creeper has feasted on noxious fumes resulting in its body being infused with powerful acids.\"\nVendor:\nShad'anis\nZone:\nK'aresh\nCost:\n7" }
entries[242733] = { ["name"] = "Blue Barry", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A particularly rare variant of slateback, \"Blue Barry\" was previously used as a beast of burden.\"\nQuest:\nA Blue for You\nZone:\nK'aresh" }
entries[242734] = { ["name"] = "Curious Slateback", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This curious slateback somehow managed to get itself stuck in a box. How it fit inside is still up in the air.\"\nDrop:\nWriggling Pinnacle Cache\nZone:\nK'aresh" }
