entries[242795] = { ["name"] = "Lana'thel's Crimson Cascade", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Blood Queen's mastery of the sanguine arts allowed her to conjure a fearsome servant to bear her into battle. Adorned in livery suited to her court, it is masked with a fearsome visage, and adorned with wings and claws to bring to mind its master's wrath.\"\nIn-Game Shop" }
