entries[243019] = { ["name"] = "Voidwing Dragonhawk", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Cutting through the skies, it flies with silent wings and eyes that glow with the echo of forgotten stars.\"\nPromotion" }
