entries[243061] = { ["name"] = "Unbound Star-Eater", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"In the void-scarred wake of the All-Devouring and his kith, twisted remnants of distant worlds and forgotten aeons find their way across the Great Dark.\"\nDrop:\nDimensius, the All-Devouring\nZone:\nManaforge Omega (Mythic)" }
